from urllib.parse import urlsplit

def destination(next_url):
    parsed = urlsplit(next_url)
    if not next_url.startswith("/") or next_url.startswith("//") or "\\" in next_url or parsed.scheme or parsed.netloc or any(ord(c) < 32 for c in next_url):
        return "/"
    return next_url

import base64
import hashlib
import hmac
import json

def session_user(cookie, key):
    try:
        body, signature = cookie.rsplit(".", 1)
        expected = hmac.new(key, body.encode(), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(signature, expected):
            return None
        return json.loads(base64.urlsafe_b64decode(body.encode()))["user"]
    except (ValueError, KeyError, TypeError):
        return None

def response_headers(origin):
    headers = {"Vary": "Origin"}
    if origin == "https://portal.example.invalid":
        headers.update({"Access-Control-Allow-Origin": origin, "Access-Control-Allow-Credentials": "true"})
    return headers

